export interface CompareSessionRepository {
  list(projectId: string): Promise<CompareSessionSummary[]>;
  read(id: string): Promise<ComparePageSession | null>;
  create(session: ComparePageSession): Promise<ComparePageSession>;
  delete(id: string): Promise<void>;
}

export function diagramTargets(history: CanvasHistoryRecord, checkpointId = history.headId): CompareDiagramTarget[] {
  const { scene } = documentFromHistory(history, checkpointId);
  const visit = (box: GridBox): CompareDiagramTarget[] => box.kind === 'container' ? box.children.flatMap(visit) : [{
    diagramId: `grid:${box.id}`, revisionId: scene.contents[box.contentId].revisionId,
    name: diagramTitle(scene.contents[box.contentId].content.ascii)?.slice(0, 200) || box.id
  }];
  return visit(scene.root);
}

/** Capture only the selected endpoint and its rendering dependencies, never the undo archive. */
export function copyCompareHistory(history: CanvasHistoryRecord, checkpointId: string): CanvasHistoryRecord {
  const checkpoint = history.snapshots[checkpointId];
  if (!checkpoint) throw new ApplicationError('conflict', 'The selected checkpoint is no longer available. Refresh the views.');
  const { parentId: _parent, transactionId: _transaction, ...head } = checkpoint;
  const revisions = Object.fromEntries(checkpointRevisionIds(checkpoint).map(id => [id, history.diagramRevisions[id]]));
  const copy: CanvasHistoryRecord = structuredClone({ schemaVersion: 1, contextId: randomUUID(),
    baselineId: checkpointId, headId: checkpointId, past: [], future: [], snapshots: { [checkpointId]: head }, diagramRevisions: revisions,
    revisionBoundary: Object.fromEntries(Object.values(revisions).flatMap(revision => revision?.parentId && !revisions[revision.parentId] ? [[revision.parentId, revision.diagramId]] : [])) });
  validateCanvasHistory(copy);
  return copy;
}

export class CompareSessionService {
  onDelete?: (id: string) => Promise<void>;
  constructor(private readonly workspace: Pick<MappingWorkspaceService, 'loadRecords'>, private readonly store: CompareSessionRepository,
    private readonly generated?: GeneratedCanvasSource,
    private readonly projects?: Pick<import('../../core/ports/diagramRepository').DiagramRepository, 'loadProject'>) {}
  private async workspaceState() {
    const { records } = await this.workspace.loadRecords('current');
    const index = records.workspace as WorkspaceIndex | undefined;
    if (!index) throw new ApplicationError('invalid-input', 'Open and save a Mapping canvas first.');
    return { records, index };
  }
  async candidates(): Promise<CompareCandidate[]> {
    const { records, index } = await this.workspaceState();
    const generated = await this.generated?.readAll() ?? [];
    const generatedById = new Map(generated.map(canvas => [canvas.id, canvas] as const));
    const workspace: CompareCandidate[] = index.documentIds.flatMap(documentId => {
      const prefix = documentPrefix(documentId), metadata = records[prefix + 'metadata'] as MappingDocumentSnapshot;
      const provenance = generatedById.get(documentId)?.generated;
      if (metadata.hidden || metadata.type === 'generated' && !provenance) return [];
      const origin = provenance ? { generated: provenance } : {};
      const history = recordHistory(records, documentId);
      return [{ documentId, checkpointId: history.headId, name: provenance ? `${metadata.name} · Current saved canvas` : 'Current saved canvas', canvasName: metadata.name, diagrams: diagramTargets(history), ...origin },
        ...Object.values(history.canvasViews?.saved ?? {}).filter(view => !view.archivedAt && view.finalCheckpointId && (!view.generation || view.generation.status === 'finished')).map(view => ({
          documentId, viewId: view.id, checkpointId: view.finalCheckpointId!, name: view.name, canvasName: metadata.name,
          diagrams: diagramTargets(history, view.finalCheckpointId!), ...origin
        }))];
    });
    return [...workspace, ...generated.flatMap(canvas => !workspace.some(item => item.documentId === canvas.id && !item.viewId && item.checkpointId === canvas.history.headId) ? [{ documentId: canvas.id, checkpointId: canvas.history.headId, name: canvas.name,
      canvasName: canvas.generated.contextName, diagrams: diagramTargets(canvas.history), generated: canvas.generated }] : [])];
  }
  async list() {
    // Listing comparison metadata needs project identity, not every live canvas checkpoint.
    const projectId = this.projects ? (await this.projects.loadProject())?.id : (await this.workspaceState()).index.projectId;
    return projectId ? this.store.list(projectId) : [];
  }
  async read(id: string) {
    const session = await this.store.read(id);
    if (!session) throw new ApplicationError('invalid-input', 'Comparison session not found.');
    return session;
  }
  async delete(id: string) { await this.read(id); await this.store.delete(id); await this.onDelete?.(id); }
  async create(input: unknown): Promise<ComparePageSession> {
    const request = createCompareSessionSchema.parse(input), requestHash = sha256(JSON.stringify(request));
    const existing = await this.store.read(request.requestId);
    if (existing) {
      if (existing.requestHash !== requestHash) throw new ApplicationError('conflict', 'Request ID already used for another comparison.');
      return existing;
    }
    const captured = await this.capture(request.pairs.flatMap(pair => [pair.A, pair.B]));
    return this.createPinned(request, captured);
  }
  async capture(sources: CompareSource[]) {
    const { records, index } = await this.workspaceState();
    const copies = new Map<string, CompareCanvasCopy>(), histories = new Map<string, CanvasHistoryRecord>();
    const createdAt = new Date().toISOString();
    const catalog = new Map(await Promise.all(sources.map(async source =>
      [JSON.stringify({ documentId: source.documentId, ...(source.viewId ? { viewId: source.viewId } : {}), checkpointId: source.checkpointId }),
        await this.generated?.read(source.documentId, source.checkpointId)] as const)));
    const capture = ({ documentId, viewId, checkpointId }: CompareSource) => {
      const source = { documentId, ...(viewId ? { viewId } : {}), checkpointId };
      const key = JSON.stringify(source);
      const previous = copies.get(key); if (previous) return previous;
      const generated = catalog.get(key);
      if (generated && !source.viewId && generated.history.snapshots[source.checkpointId]) {
        const history = copyCompareHistory(generated.history, source.checkpointId);
        history.snapshots[source.checkpointId].view ??= initialCanvasState();
        const copy: CompareCanvasCopy = { id: randomUUID(), source, canvasName: generated.generated.contextName, history, generated: structuredClone(generated.generated),
          view: { id: randomUUID(), name: generated.name, createdAt, savedAt: createdAt,
            startCheckpointId: source.checkpointId, finalCheckpointId: source.checkpointId, checkpointIds: [source.checkpointId] } };
        copies.set(key, copy); return copy;
      }
      if (!index.documentIds.includes(source.documentId)) throw new ApplicationError('invalid-input', 'Unknown canvas.');
      const prefix = documentPrefix(source.documentId), metadata = records[prefix + 'metadata'] as MappingDocumentSnapshot;
      if (metadata.type === 'generated' && !generated) throw new ApplicationError('invalid-input', 'The generated snapshot is unavailable.');
      let history = histories.get(source.documentId);
      if (!history) { history = recordHistory(records, source.documentId); histories.set(source.documentId, history); }
      const view = source.viewId ? history.canvasViews?.saved[source.viewId] : undefined;
      if (source.viewId && (!view || view.archivedAt || view.finalCheckpointId !== source.checkpointId)
        || !source.viewId && history.headId !== source.checkpointId)
        throw new ApplicationError('conflict', 'The selected view changed. Refresh the views and try again.');
      const copiedHistory = copyCompareHistory(history, source.checkpointId);
      const checkpoint = copiedHistory.snapshots[source.checkpointId];
      const canvas = (checkpoint.view ?? initialCanvasState()) as MappingCanvasState;
      if (!source.viewId && records[prefix + 'viewport']) canvas.viewport = structuredClone(records[prefix + 'viewport']) as MappingCanvasState['viewport'];
      checkpoint.view = canvas;
      // Resolve and validate presentation data before publishing a session.
      const document = documentFromHistory(copiedHistory);
      deserializeWorkspace({ schemaVersion: 3, projectId: index.projectId, documents: [{
        representationId: source.documentId, name: metadata.name, revisionId: 'compare-snapshot', savedName: metadata.name,
        savedScene: JSON.stringify(document.scene), savedEdges: JSON.stringify(document.edges), document, canvas
      }] });
      const copy: CompareCanvasCopy = { id: randomUUID(), source, canvasName: generated?.generated.contextName ?? metadata.name, history: copiedHistory,
        ...(generated ? { generated: structuredClone(generated.generated) } : {}),
        view: { id: randomUUID(), name: view?.name ?? metadata.name, createdAt, savedAt: createdAt,
          startCheckpointId: source.checkpointId, finalCheckpointId: source.checkpointId, checkpointIds: [source.checkpointId],
          ...(view?.generation ? { generation: structuredClone(view.generation) } : {}) } };
      copies.set(key, copy); return copy;
    };
    sources.forEach(capture);
    return { projectId: index.projectId, canvases: [...copies.values()] };
  }
  async createPinned(input: unknown, captured: { projectId: string; canvases: CompareCanvasCopy[] }): Promise<ComparePageSession> {
    const request = createCompareSessionSchema.parse(input), requestHash = sha256(JSON.stringify(request));
    const copies = new Map(captured.canvases.map(copy => [JSON.stringify(copy.source), structuredClone(copy)]));
    const capture = ({ documentId, viewId, checkpointId }: CompareSource) => {
      const copy = copies.get(JSON.stringify({ documentId, ...(viewId ? { viewId } : {}), checkpointId }));
      if (!copy) throw new ApplicationError('invalid-input', 'Comparison source was not captured.');
      return copy;
    };
    const createdAt = new Date().toISOString();
    const pane = (copy: CompareCanvasCopy) => {
      const canvas = copy.history.snapshots[copy.history.headId].view as MappingCanvasState;
      // Same default as Mapping's native camera (360, 100, 1), in persisted coordinates.
      return { canvasCopyId: copy.id, camera: { transform: structuredClone(canvas?.viewport ?? { offset: { x: 170, y: 36 }, scale: 1 }) } };
    };
    const compares = request.pairs.map(pair => {
      const A = capture(pair.A), B = capture(pair.B);
      if (pair.A.diagram && pair.B.diagram) {
        const diagramPane = (copy: CompareCanvasCopy, target: NonNullable<CreateCompareSession['pairs'][number]['A']['diagram']>): CompareDiagramPaneSpec => {
          const pinned = diagramTargets(copy.history).find(item => item.diagramId === target.diagramId);
          if (!pinned) throw new ApplicationError('invalid-input', `Unknown diagram: ${target.diagramId}`);
          if (pinned.revisionId !== target.revisionId) throw new ApplicationError('conflict', 'The selected diagram revision does not match this snapshot. Refresh the views.');
          if (target.ranges?.some(range => range.endLine > copy.history.diagramRevisions[target.revisionId].diagram.content.ascii.split('\n').length))
            throw new ApplicationError('invalid-input', 'Comparison slice is outside the diagram.');
          if (target.nodeRef) {
            try { revisionScope(copy.history.diagramRevisions[target.revisionId], target.nodeRef); }
            catch { throw new ApplicationError('invalid-input', 'The selected subtree does not exist in this revision.'); }
          }
          return { kind: 'diagram', canvasCopyId: copy.id, ...target };
        };
        return { id: randomUUID(), title: pair.title ?? `${A.view.name} / ${B.view.name}`, ...(pair.explanation ? { explanation: pair.explanation } : {}), A: diagramPane(A, pair.A.diagram), B: diagramPane(B, pair.B.diagram) };
      }
      const diagrams = (copy: CompareCanvasCopy) => {
        const document = documentFromHistory(copy.history);
        return flattenGrid(resolveScene(document.scene)).filter(box => box.box.kind === 'diagram' && box.contentId)
          .sort((a, b) => a.bounds.row - b.bounds.row || a.bounds.column - b.bounds.column || a.box.id.localeCompare(b.box.id))
          .map(box => ({ id: `grid:${box.box.id}`, title: document.scene.contents[box.contentId!].content.ascii.split('\n').find(line => line.trim())?.slice(0, 200) || 'Diagram' }));
      };
      const targetsA = diagrams(A), targetsB = diagrams(B);
      // A self-comparison is the manual smoke-test tour, with explicit identical targets.
      const focusPairs = pair.focusPairs ?? (A.id === B.id ? targetsA.slice(0, 3).map(target => ({ title: target.title, A: target.id, B: target.id })) : []);
      const camera = (copy: CompareCanvasCopy, target: string, title: string, targets: typeof targetsA) => {
        if (!targets.some(item => item.id === target)) throw new ApplicationError('invalid-input', `Unknown diagram focus: ${target}`);
        const cameras = copy.view.cameraViews ??= [];
        const existing = cameras.find(camera => camera.focus.type === 'DiagramFocused' && camera.focus.diagramId === target);
        if (existing) return existing.id;
        const id = randomUUID(); cameras.push({ id, title, focus: { type: 'DiagramFocused', diagramId: target } });
        copy.view.defaultCameraViewId ??= id;
        return id;
      };
      const points = focusPairs.map(point => ({ id: randomUUID(), title: point.title,
        A: camera(A, point.A, point.title, targetsA), B: camera(B, point.B, point.title, targetsB) }));
      return { id: randomUUID(), title: A.id === B.id ? A.view.name : `${A.view.name} / ${B.view.name}`, A: pane(A), B: pane(B), ...(points.length ? { points } : {}) };
    });
    return this.store.create({ schemaVersion: 1, id: request.requestId, projectId: captured.projectId, title: request.title,
      createdAt, requestHash, canvases: [...copies.values()], compares });
  }
}
"},{"path":"domain/mapping/evals/evalRun.ts","text":"import { z } from 'zod';
import { compareSourceSchema, type CompareCanvasCopy, type CompareSource } from '../compare/comparePageSession';
import type { RollUpRun } from '../rollup/rollUp';
import { evalWorkflowIds, type EvalWorkflowId } from './evalWorkflows';
import { savedAgentContextIdSchema } from '../../core/agents/savedAgentContext';

const id = z.string().regex(/^[A-Za-z0-9][A-Za-z0-9_-]{0,80}$/);
export const evalRunRequestSchema = z.object({
  requestId: z.string().uuid(), workflow: z.enum(evalWorkflowIds),
  prompts: z.array(z.object({ promptId: id, version: z.number().int().positive() }).strict()).min(1).max(6)
    .refine(items => new Set(items.map(item => item.promptId)).size === items.length, 'Select each prompt once'),
  /** Canvas inputs pin a checkpoint; AgentContext inputs are immutable by ID. */
  inputs: z.record(z.string().regex(/^[a-z][a-z0-9_]*$/), z.union([compareSourceSchema, z.object({ agentContextId: savedAgentContextIdSchema }).strict()])),
  /** Earlier generated canvases attached as extra input (Alternatives). */
  canvasSources: z.array(compareSourceSchema).max(20).optional(),
  previous: z.array(z.string().regex(/^[A-Za-z0-9][A-Za-z0-9_-]{0,80}$/)).max(6).optional(),
  referenceIds: z.array(id).max(30).refine(ids => new Set(ids).size === ids.length, "Select each reference once").optional(),
  layoutTemplateId: id.optional(),
  passes: z.number().int().min(1).max(20).default(1),
  model: z.string().trim().min(1).max(100).default('gpt-6-sol'),
  effort: z.enum(['low', 'medium', 'high', 'xhigh']).default('high'),
  /** Omitted on historical runs, which continue to use context.json. */
  contextDelivery: z.literal('session').optional(),
  /** Reruns are filed under the original run and share its AgentContext. */
  parentRunId: id.optional()
}).strict().refine(input => !input.contextDelivery || input.workflow === 'diagram-change-proposal',
  'Session context delivery is supported by diagram-change-proposal.').refine(input => !input.canvasSources?.length || input.workflow === 'linked-canvases',
  'Canvas sets are supported by Linked canvases.');
export type EvalRunRequest = z.infer<typeof evalRunRequestSchema>;
export const renameEvalRunSchema = z.object({ name: z.string().trim().max(120) }).strict();
export const evalEfforts = ['low', 'medium', 'high', 'xhigh'] as const;

/** Prompt text is pinned into the run; later prompt edits never change what a run means. */
export interface EvalRunPrompt { templateBase?: import('./promptTemplateBase').PromptTemplateBase; parents?: import('./evalPrompt').PromptParent[]; contentHash?: string; derivation?: import('./evalPrompt').PromptDerivation; promptId: string; version?: number; name: string; stages: Record<string, string>;
  /** Text of the references the stages cite, frozen when the run starts. */
  references?: Record<string, { name: string; ascii: string; comment?: string }> }
export type EvalCellStatus = 'queued' | 'generating' | 'finished' | 'failed' | 'skipped' | 'cancelled';
export interface EvalRunCell {
  /** Payloads stay in the shared checkpoint store, not duplicated in each run. */
  historyArtifact?: { timelineId: string; stepId: string };
  /** Multi-canvas result metadata; full frozen documents are stored once in the run. */
  output?: import('./evalOutputResult').EvalOutputSummary;
  layoutPlacements?: import('../../core/diagrams/layoutTemplate').LayoutPlacement[];
  candidateName?: string;
  /** Exact proposal output, retained independently of display canvas edits. */
  proposalTree?: string;
  key: string; promptId?: string; promptVersion?: number; promptName?: string; pass: number; stage: string;
  status: EvalCellStatus; canvasId?: string; checkpointId?: string; explanation?: string; error?: string;
  usage?: Record<string, number>; startedAt?: string; completedAt?: string;
  execution?: { runtime: 'pi-agent-context'; sessionId: string; contextHash: string; cacheKey: string };
  /** Set on summaries when the output canvas was deleted. */
  deleted?: boolean;
}
export type EvalRunStatus = 'queued' | 'generating' | 'finished' | 'failed' | 'partial' | 'cancelled';
export interface EvalRun {
  /** A durable external coordinator owns recovery; server startup must not cancel it. */
  coordinator?: 'diagram-history';
  historyInput?: { timelineId: string; stepId: string; batchId: string; scaffoldStepId?: string };
  canvasInputs?: CompareCanvasCopy[];
  outputResults?: Record<string, import('./evalOutputResult').EvalOutputResult>;
  layoutTemplate?: import('../../core/diagrams/layoutTemplate').LayoutTemplate;
  number?: number;
  deletedAt?: string;
  outputSnapshots?: Record<string, import('../../core/diagrams/generatedCanvas').GeneratedCanvasRecord>;
  /** Compatibility records retain their original request and child chat identities. */
  compatibility?: { kind: 'chat-alternatives'; requestId?: string; parentChatId: string; candidates: { viewId: string; chatId: string; name: string }[] };
  schemaVersion: 1; id: string; requestHash: string; request: EvalRunRequest & { /** Historical records only; rejected on new requests. */ task?: string }; projectId: string; workflow: EvalWorkflowId;
  agentContextId: string; contextName: string; prompts: EvalRunPrompt[]; inputs: Record<string, CompareCanvasCopy>;
  /** AgentContext inputs, recorded with the hash they had when the run started. */
  contexts?: Record<string, EvalRunContext>;
  /** Pinned copies of earlier alternatives attached to every prompt. */
  previous?: CompareCanvasCopy[];
  references?: import("./evalReference").EvalReference[];
  status: EvalRunStatus; createdAt: string; completedAt?: string; error?: string; cells: EvalRunCell[];
  /** The original run this one reruns; always a root run, never another rerun. */
  parentRunId?: string;
  /** Shown in place of the prompt names in the explorer. */
  name?: string;
  /** Pre-Evals roll-up runs. Their prompt text was not recorded. */
  legacy?: boolean;
}
export interface EvalRunContext { agentContextId: string; name: string; contentHash: string }
export interface EvalRunInputSummary { source: CompareSource; name: string; canvasName: string; generated?: import('../../core/diagrams/generatedCanvas').GeneratedCanvas }
export type EvalRunSummary = Omit<EvalRun, 'inputs' | 'previous' | 'requestHash' | 'outputSnapshots' | 'outputResults' | 'canvasInputs'> & { inputs: Record<string, EvalRunInputSummary>; previousNames?: string[]; previousInputs?: EvalRunInputSummary[]; canvasInputs?: EvalRunInputSummary[];
  /** Judgements own their attachments, allowing one result to evaluate several runs. */
  judgements?: import('./judgement').JudgementSummary[] };

export const cellKey = (promptId: string | undefined, pass: number, stage: string) => `${promptId ?? 'unknown'}:${pass}:${stage}`;
export function summarizeEvalRun({ inputs, previous, canvasInputs, outputSnapshots: _snapshots, outputResults: _results, requestHash: _, ...run }: EvalRun): EvalRunSummary {
  return { ...run, ...(canvasInputs ? { canvasInputs: canvasInputs.map(copy => ({ source: copy.source, name: copy.view.name, canvasName: copy.canvasName })) } : {}), ...(previous?.length ? { previousNames: previous.map(copy => copy.view.name), previousInputs: previous.map(copy => ({ source: copy.source, name: copy.view.name, canvasName: copy.canvasName, ...(copy.generated ? { generated: copy.generated } : {}) })) } : {}), inputs: Object.fromEntries(Object.entries(inputs).map(([name, copy]) => [name, { source: copy.source, name: copy.view.name, canvasName: copy.canvasName }])) };
}
/** A bundle is one output; its canvases are navigated inside the preview. */
export const hasEvalOutput = (cell: EvalRunCell) => !!cell.output?.canvases.length || !!cell.canvasId && !cell.deleted;
export function runStatus(cells: EvalRunCell[]): EvalRunStatus {
  if (cells.some(cell => cell.status === 'generating')) return 'generating';
  if (cells.some(cell => cell.status === 'queued')) return cells.some(cell => cell.status !== 'queued') ? 'generating' : 'queued';
  if (cells.every(cell => cell.status === 'finished')) return 'finished';
  if (cells.some(cell => cell.status === 'finished')) return 'partial';
  return !cells.some(cell => cell.status === 'failed') && cells.some(cell => cell.status === 'cancelled') ? 'cancelled' : 'failed';
}

export function legacyRollUpRun(run: RollUpRun): EvalRun {
  const passes = run.request.passes;
  const cells: EvalRunCell[] = [];
  for (let pass = 1; pass <= passes; pass++) for (const stage of ['r2', 'g2']) {
    const output = run.outputs.find(item => item.pass === pass && item.stage === stage);
    cells.push({ key: cellKey(undefined, pass, stage), pass, stage, canvasId: output?.canvasId, explanation: output?.explanation, usage: output?.usage,
      status: output ? 'finished' : run.status === 'failed' ? 'failed' : run.status === 'finished' ? 'skipped' : 'queued',
      ...(!output && run.status === 'failed' ? { error: run.error } : {}) });
  }
  return { schemaVersion: 1, id: run.id, requestHash: run.requestHash, projectId: run.projectId, workflow: 'roll-up', legacy: true,
    request: { requestId: run.id, workflow: 'roll-up', prompts: [], inputs: { child: run.request.child, parent: run.request.parent },
      passes, model: run.request.model, effort: run.request.effort as EvalRunRequest['effort'] },
    agentContextId: run.agentContextId, contextName: run.contextName, prompts: [], inputs: { child: run.child, parent: run.parent },
    status: run.status, createdAt: run.createdAt, completedAt: run.completedAt, error: run.error, cells };
}
"},{"path":"infrastructure/mapping/evals/agentContextEvalRuntime.ts","text":"import { EVAL_GENERATION_TIMEOUT_MS } from '../../../domain/mapping/evals/evalLimits';
import { DefaultResourceLoader, getAgentDir, SettingsManager } from '@earendil-works/pi-coding-agent';
import { AgentContext } from '../../../domain/core/agents/agentContext';
import { sha256 } from '../../../domain/core/sha256';
import type { EvalRuntime } from '../../../application/mapping/evals/evalRunService';
import { PiAgentRuntime } from '../../core/agents/agentRuntime';
import { CodexEvalRuntime } from './evalRuntime';

/** Independent persisted sessions share a resolved history prefix, never another sample's answer. */
export class AgentContextEvalRuntime extends PiAgentRuntime implements EvalRuntime {
  private readonly legacy: CodexEvalRuntime;
  constructor(private readonly cwd: string, enabled = false) {
    super(enabled); this.legacy = new CodexEvalRuntime(enabled);
  }
  async generate(input: Parameters<EvalRuntime['generate']>[0]): ReturnType<EvalRuntime['generate']> {
    if (!input.agentContext) return this.legacy.generate(input);
    this.requireEnabled(); input.signal.throwIfAborted();
    const context = AgentContext.fromSnapshot(input.agentContext);
    // Fail before opening a session if collection did not resolve every source reference.
    context.toPiMessages();
    const configured = await this.model(input.model);
    const effort = input.effort as 'low' | 'medium' | 'high' | 'xhigh';
    const settingsManager = SettingsManager.inMemory({ defaultProvider: configured.provider, defaultModel: configured.modelId,
      defaultThinkingLevel: effort, compaction: { enabled: false }, retry: { enabled: false }, transport: 'sse' });
    const resourceLoader = new DefaultResourceLoader({ cwd: this.cwd, agentDir: getAgentDir(), settingsManager,
      noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
      systemPrompt: 'You are a helpful assistant.' });
    await resourceLoader.reload(); input.signal.throwIfAborted();
    const { session } = await this.createSession({ cwd: this.cwd, modelRuntime: configured.runtime, model: configured.model,
      thinkingLevel: effort, tools: [], resourceLoader, settingsManager }, context);
    const cacheKey = `eval-${sha256(JSON.stringify([configured.provider, configured.modelId, effort, session.systemPrompt, context.contentHash]))}`;
    // Pi normally uses the unique session ID as its cache key. Keep independent audit IDs,
    // but route identical prefixes together. SSE prevents shared WebSocket conversation state.
    const stream = session.agent.streamFunction;
    session.agent.streamFunction = (model, history, options) => stream(model, history, { ...options, sessionId: cacheKey, transport: 'sse' });
    const usage: Record<string, number> = {};
    let text: string | undefined, failure: string | undefined;
    const unsubscribe = session.subscribe(event => {
      if (event.type !== 'message_end' || event.message.role !== 'assistant') return;
      const message = event.message;
      for (const [key, value] of Object.entries(message.usage)) if (typeof value === 'number') usage[key] = (usage[key] ?? 0) + value;
      if (message.stopReason === 'error' || message.stopReason === 'aborted') failure = message.errorMessage || message.stopReason;
      text = message.content.flatMap(block => block.type === 'text' ? [block.text] : []).join('');
    });
    const abort = () => { void session.abort().catch(() => {}); };
    let timedOut = false;
    const timeout = setTimeout(() => { timedOut = true; abort(); }, EVAL_GENERATION_TIMEOUT_MS);
    input.signal.addEventListener('abort', abort, { once: true });
    try {
      input.signal.throwIfAborted();
      const supplementary = Object.keys(input.files).length ? `\n\n${JSON.stringify(input.files)}` : '';
      await session.prompt(input.prompt + supplementary);
      input.signal.throwIfAborted();
      if (timedOut) throw Error('Generation timed out.');
      if (failure) throw Error(`Eval agent failed: ${failure}`);
      if (text === undefined) throw Error('Eval agent returned no assistant response');
      // Malformed envelopes go through the existing bounded validation retry, with raw evidence retained.
      let output: unknown = text;
      try { output = JSON.parse(text); } catch { /* The workflow validator reports the envelope error. */ }
      return { output, usage, execution: { runtime: 'pi-agent-context', sessionId: session.sessionId, contextHash: context.contentHash, cacheKey } };
    } finally {
      clearTimeout(timeout); input.signal.removeEventListener('abort', abort);
      unsubscribe(); session.dispose(); this.sessions.delete(session);
    }
  }
}
