16:   constructor(private store: JudgementStore, private sessions: CompareSessionService, private comparisonStore: ComparisonRunStore,
17:     private comparisons: ComparisonGenerationService, private runs: EvalRunStore) {
18:     this.queue = store.list().then(async records => {
19:       for (const item of records) if (item.source.kind === 'eval-run' && !item.deletedAt && ['queued', 'generating'].includes(item.status))
