25:   }
26:   private async reconcile() {
27:     const [sessions, jobs, existing, runs] = await Promise.all([this.sessions.list(), this.comparisonStore.list(), this.store.list(), this.runs.list()]);
28:     const records = new Map(existing.map(item => [item.id, item]));
29:     const jobsById = new Map(jobs.map(job => [job.sessionId ?? job.id, job]));
30:     const sources = new Set([...sessions.map(item => item.id), ...jobs.map(item => item.id)]);
31:     const subjects = (canvases: CompareCanvasCopy[]): JudgementSubject[] => canvases.map(copy => {
32:       const owner = runs.find(run => run.id === copy.generated?.runId) ?? runs.find(run => run.cells.some(cell => cell.canvasId === copy.source.documentId));
33:       const runId = owner?.id ?? copy.generated?.runId;
34:       const outputKey = owner?.cells.find(cell => cell.canvasId === copy.source.documentId)?.key;
35:       return { source: copy.source, ...(runId ? { runId } : {}), ...(outputKey ? { outputKey } : {}) };
