53:         ...(diagrams.length ? { data: diagramJudgementSchema.parse({ comparisons: diagrams }) } : {}) });
54:       if (canvasesCompared.length) results.push({ ...common, id: `${sourceId}-canvas`, kind: 'canvas-comparison', data: canvasJudgementSchema.parse({
55:         comparisons: canvasesCompared.map(pair => ({ ...pair, A: { ...pair.A, kind: 'canvas' }, B: { ...pair.B, kind: 'canvas' } }))
56:       }) });
57:       for (const result of results) {
58:         if (result.data && result.kind !== 'few-shot-progress' && result.kind !== 'comparison-report' && result.kind !== 'diagram-change-tree') {
59:           const used = new Set(result.data.comparisons.flatMap(pair => [pair.A.canvasCopyId, pair.B.canvasCopyId]));
60:           result.canvases = canvases.filter(copy => used.has(copy.id));
61:           result.subjects = subjects(result.canvases);
62:           result.runIds = [...new Set(result.subjects.flatMap(ref => ref.runId ? [ref.runId] : []))];
63:         }
64:         const previous = records.get(result.id);
65:         if (previous?.deletedAt) continue;
66:         if (!previous || previous.status !== result.status || previous.source.fingerprint !== result.source.fingerprint || JSON.stringify(previous.subjects) !== JSON.stringify(result.subjects)) await this.store.save(result);
67:       }
68:     };
69:     for (const summary of sessions) {
70:       const job = jobsById.get(summary.id);
71:       // Completed session snapshots never change; avoid loading them again during polling.
72:       const previous = existing.filter(item => item.source.id === summary.id);
73:       if (previous.length && previous.every(item => item.deletedAt || item.status === 'finished' && item.source.fingerprint === fingerprint(job) && item.subjects.every(ref => ref.runId))) continue;
