87:     const request = createCompareSessionSchema.parse(input), requestHash = sha256(JSON.stringify(request));
88:     const existing = await this.store.read(request.requestId);
89:     if (existing) {
90:       if (existing.requestHash !== requestHash) throw new ApplicationError('conflict', 'Request ID already used for another comparison.');
91:       return existing;
92:     }
93:     const captured = await this.capture(request.pairs.flatMap(pair => [pair.A, pair.B]));
94:     return this.createPinned(request, captured);
95:   }
96:   async capture(sources: CompareSource[]) {
97:     const { records, index } = await this.workspaceState();
98:     const copies = new Map<string, CompareCanvasCopy>(), histories = new Map<string, CanvasHistoryRecord>();
99:     const createdAt = new Date().toISOString();
100:     const catalog = new Map(await Promise.all(sources.map(async source =>
101:       [JSON.stringify({ documentId: source.documentId, ...(source.viewId ? { viewId: source.viewId } : {}), checkpointId: source.checkpointId }),
102:         await this.generated?.read(source.documentId, source.checkpointId)] as const)));
103:     const capture = ({ documentId, viewId, checkpointId }: CompareSource) => {
104:       const source = { documentId, ...(viewId ? { viewId } : {}), checkpointId };
105:       const key = JSON.stringify(source);
106:       const previous = copies.get(key); if (previous) return previous;
107:       const generated = catalog.get(key);
108:       if (generated && !source.viewId && generated.history.snapshots[source.checkpointId]) {
109:         const history = copyCompareHistory(generated.history, source.checkpointId);
110:         history.snapshots[source.checkpointId].view ??= initialCanvasState();
111:         const copy: CompareCanvasCopy = { id: randomUUID(), source, canvasName: generated.generated.contextName, history, generated: structuredClone(generated.generated),
112:           view: { id: randomUUID(), name: generated.name, createdAt, savedAt: createdAt,
113:             startCheckpointId: source.checkpointId, finalCheckpointId: source.checkpointId, checkpointIds: [source.checkpointId] } };
114:         copies.set(key, copy); return copy;
115:       }
116:       if (!index.documentIds.includes(source.documentId)) throw new ApplicationError('invalid-input', 'Unknown canvas.');
117:       const prefix = documentPrefix(source.documentId), metadata = records[prefix + 'metadata'] as MappingDocumentSnapshot;
118:       if (metadata.type === 'generated' && !generated) throw new ApplicationError('invalid-input', 'The generated snapshot is unavailable.');
119:       let history = histories.get(source.documentId);
120:       if (!history) { history = recordHistory(records, source.documentId); histories.set(source.documentId, history); }
121:       const view = source.viewId ? history.canvasViews?.saved[source.viewId] : undefined;
122:       if (source.viewId && (!view || view.archivedAt || view.finalCheckpointId !== source.checkpointId)
123:         || !source.viewId && history.headId !== source.checkpointId)
124:         throw new ApplicationError('conflict', 'The selected view changed. Refresh the views and try again.');
125:       const copiedHistory = copyCompareHistory(history, source.checkpointId);
126:       const checkpoint = copiedHistory.snapshots[source.checkpointId];
127:       const canvas = (checkpoint.view ?? initialCanvasState()) as MappingCanvasState;
128:       if (!source.viewId && records[prefix + 'viewport']) canvas.viewport = structuredClone(records[prefix + 'viewport']) as MappingCanvasState['viewport'];
129:       checkpoint.view = canvas;
130:       // Resolve and validate presentation data before publishing a session.
131:       const document = documentFromHistory(copiedHistory);
132:       deserializeWorkspace({ schemaVersion: 3, projectId: index.projectId, documents: [{
133:         representationId: source.documentId, name: metadata.name, revisionId: 'compare-snapshot', savedName: metadata.name,
134:         savedScene: JSON.stringify(document.scene), savedEdges: JSON.stringify(document.edges), document, canvas
135:       }] });
136:       const copy: CompareCanvasCopy = { id: randomUUID(), source, canvasName: generated?.generated.contextName ?? metadata.name, history: copiedHistory,
137:         ...(generated ? { generated: structuredClone(generated.generated) } : {}),
138:         view: { id: randomUUID(), name: view?.name ?? metadata.name, createdAt, savedAt: createdAt,
139:           startCheckpointId: source.checkpointId, finalCheckpointId: source.checkpointId, checkpointIds: [source.checkpointId],
140:           ...(view?.generation ? { generation: structuredClone(view.generation) } : {}) } };
141:       copies.set(key, copy); return copy;
142:     };
143:     sources.forEach(capture);
144:     return { projectId: index.projectId, canvases: [...copies.values()] };
145:   }
146:   async createPinned(input: unknown, captured: { projectId: string; canvases: CompareCanvasCopy[] }): Promise<ComparePageSession> {
147:     const request = createCompareSessionSchema.parse(input), requestHash = sha256(JSON.stringify(request));
148:     const copies = new Map(captured.canvases.map(copy => [JSON.stringify(copy.source), structuredClone(copy)]));
149:     const capture = ({ documentId, viewId, checkpointId }: CompareSource) => {
150:       const copy = copies.get(JSON.stringify({ documentId, ...(viewId ? { viewId } : {}), checkpointId }));
151:       if (!copy) throw new ApplicationError('invalid-input', 'Comparison source was not captured.');
152:       return copy;
153:     };
154:     const createdAt = new Date().toISOString();
155:     const pane = (copy: CompareCanvasCopy) => {
156:       const canvas = copy.history.snapshots[copy.history.headId].view as MappingCanvasState;
157:       // Same default as Mapping's native camera (360, 100, 1), in persisted coordinates.
158:       return { canvasCopyId: copy.id, camera: { transform: structuredClone(canvas?.viewport ?? { offset: { x: 170, y: 36 }, scale: 1 }) } };
159:     };
160:     const compares = request.pairs.map(pair => {
161:       const A = capture(pair.A), B = capture(pair.B);
162:       if (pair.A.diagram && pair.B.diagram) {
163:         const diagramPane = (copy: CompareCanvasCopy, target: NonNullable<CreateCompareSession['pairs'][number]['A']['diagram']>): CompareDiagramPaneSpec => {
164:           const pinned = diagramTargets(copy.history).find(item => item.diagramId === target.diagramId);
165:           if (!pinned) throw new ApplicationError('invalid-input', `Unknown diagram: ${target.diagramId}`);
166:           if (pinned.revisionId !== target.revisionId) throw new ApplicationError('conflict', 'The selected diagram revision does not match this snapshot. Refresh the views.');
167:           if (target.ranges?.some(range => range.endLine > copy.history.diagramRevisions[target.revisionId].diagram.content.ascii.split('\n').length))
168:             throw new ApplicationError('invalid-input', 'Comparison slice is outside the diagram.');
169:           if (target.nodeRef) {
170:             try { revisionScope(copy.history.diagramRevisions[target.revisionId], target.nodeRef); }
171:             catch { throw new ApplicationError('invalid-input', 'The selected subtree does not exist in this revision.'); }
172:           }
173:           return { kind: 'diagram', canvasCopyId: copy.id, ...target };
174:         };
175:         return { id: randomUUID(), title: pair.title ?? `${A.view.name} / ${B.view.name}`, ...(pair.explanation ? { explanation: pair.explanation } : {}), A: diagramPane(A, pair.A.diagram), B: diagramPane(B, pair.B.diagram) };
176:       }
177:       const diagrams = (copy: CompareCanvasCopy) => {
178:         const document = documentFromHistory(copy.history);
179:         return flattenGrid(resolveScene(document.scene)).filter(box => box.box.kind === 'diagram' && box.contentId)
180:           .sort((a, b) => a.bounds.row - b.bounds.row || a.bounds.column - b.bounds.column || a.box.id.localeCompare(b.box.id))
181:           .map(box => ({ id: `grid:${box.box.id}`, title: document.scene.contents[box.contentId!].content.ascii.split('\n').find(line => line.trim())?.slice(0, 200) || 'Diagram' }));
182:       };
183:       const targetsA = diagrams(A), targetsB = diagrams(B);
184:       // A self-comparison is the manual smoke-test tour, with explicit identical targets.
185:       const focusPairs = pair.focusPairs ?? (A.id === B.id ? targetsA.slice(0, 3).map(target => ({ title: target.title, A: target.id, B: target.id })) : []);
186:       const camera = (copy: CompareCanvasCopy, target: string, title: string, targets: typeof targetsA) => {
187:         if (!targets.some(item => item.id === target)) throw new ApplicationError('invalid-input', `Unknown diagram focus: ${target}`);
188:         const cameras = copy.view.cameraViews ??= [];
189:         const existing = cameras.find(camera => camera.focus.type === 'DiagramFocused' && camera.focus.diagramId === target);
190:         if (existing) return existing.id;
191:         const id = randomUUID(); cameras.push({ id, title, focus: { type: 'DiagramFocused', diagramId: target } });
192:         copy.view.defaultCameraViewId ??= id;
193:         return id;
194:       };
195:       const points = focusPairs.map(point => ({ id: randomUUID(), title: point.title,
196:         A: camera(A, point.A, point.title, targetsA), B: camera(B, point.B, point.title, targetsB) }));
197:       return { id: randomUUID(), title: A.id === B.id ? A.view.name : `${A.view.name} / ${B.view.name}`, A: pane(A), B: pane(B), ...(points.length ? { points } : {}) };
198:     });
199:     return this.store.create({ schemaVersion: 1, id: request.requestId, projectId: captured.projectId, title: request.title,
200:       createdAt, requestHash, canvases: [...copies.values()], compares });
201:   }
202: }

