1: import { EVAL_GENERATION_TIMEOUT_MS } from '../../../domain/mapping/evals/evalLimits';
2: import { DefaultResourceLoader, getAgentDir, SettingsManager } from '@earendil-works/pi-coding-agent';
3: import { AgentContext } from '../../../domain/core/agents/agentContext';
4: import { sha256 } from '../../../domain/core/sha256';
5: import type { EvalRuntime } from '../../../application/mapping/evals/evalRunService';
6: import { PiAgentRuntime } from '../../core/agents/agentRuntime';
7: import { CodexEvalRuntime } from './evalRuntime';
8: 
9: /** Independent persisted sessions share a resolved history prefix, never another sample's answer. */
10: export class AgentContextEvalRuntime extends PiAgentRuntime implements EvalRuntime {
11:   private readonly legacy: CodexEvalRuntime;
12:   constructor(private readonly cwd: string, enabled = false) {
13:     super(enabled); this.legacy = new CodexEvalRuntime(enabled);
14:   }
15:   async generate(input: Parameters<EvalRuntime['generate']>[0]): ReturnType<EvalRuntime['generate']> {
16:     if (!input.agentContext) return this.legacy.generate(input);
17:     this.requireEnabled(); input.signal.throwIfAborted();
18:     const context = AgentContext.fromSnapshot(input.agentContext);
19:     // Fail before opening a session if collection did not resolve every source reference.
20:     context.toPiMessages();
21:     const configured = await this.model(input.model);
22:     const effort = input.effort as 'low' | 'medium' | 'high' | 'xhigh';
23:     const settingsManager = SettingsManager.inMemory({ defaultProvider: configured.provider, defaultModel: configured.modelId,
24:       defaultThinkingLevel: effort, compaction: { enabled: false }, retry: { enabled: false }, transport: 'sse' });
25:     const resourceLoader = new DefaultResourceLoader({ cwd: this.cwd, agentDir: getAgentDir(), settingsManager,
26:       noExtensions: true, noSkills: true, noPromptTemplates: true, noThemes: true, noContextFiles: true,
27:       systemPrompt: 'You are a helpful assistant.' });
28:     await resourceLoader.reload(); input.signal.throwIfAborted();
29:     const { session } = await this.createSession({ cwd: this.cwd, modelRuntime: configured.runtime, model: configured.model,
30:       thinkingLevel: effort, tools: [], resourceLoader, settingsManager }, context);
31:     const cacheKey = `eval-${sha256(JSON.stringify([configured.provider, configured.modelId, effort, session.systemPrompt, context.contentHash]))}`;
32:     // Pi normally uses the unique session ID as its cache key. Keep independent audit IDs,
33:     // but route identical prefixes together. SSE prevents shared WebSocket conversation state.
34:     const stream = session.agent.streamFunction;
35:     session.agent.streamFunction = (model, history, options) => stream(model, history, { ...options, sessionId: cacheKey, transport: 'sse' });
36:     const usage: Record<string, number> = {};
37:     let text: string | undefined, failure: string | undefined;
38:     const unsubscribe = session.subscribe(event => {
39:       if (event.type !== 'message_end' || event.message.role !== 'assistant') return;
40:       const message = event.message;
41:       for (const [key, value] of Object.entries(message.usage)) if (typeof value === 'number') usage[key] = (usage[key] ?? 0) + value;
42:       if (message.stopReason === 'error' || message.stopReason === 'aborted') failure = message.errorMessage || message.stopReason;
43:       text = message.content.flatMap(block => block.type === 'text' ? [block.text] : []).join('');
44:     });
45:     const abort = () => { void session.abort().catch(() => {}); };
46:     let timedOut = false;
47:     const timeout = setTimeout(() => { timedOut = true; abort(); }, EVAL_GENERATION_TIMEOUT_MS);
48:     input.signal.addEventListener('abort', abort, { once: true });
49:     try {
50:       input.signal.throwIfAborted();
51:       const supplementary = Object.keys(input.files).length ? `\n\n${JSON.stringify(input.files)}` : '';
52:       await session.prompt(input.prompt + supplementary);
53:       input.signal.throwIfAborted();
54:       if (timedOut) throw Error('Generation timed out.');
55:       if (failure) throw Error(`Eval agent failed: ${failure}`);
56:       if (text === undefined) throw Error('Eval agent returned no assistant response');
57:       // Malformed envelopes go through the existing bounded validation retry, with raw evidence retained.
58:       let output: unknown = text;
59:       try { output = JSON.parse(text); } catch { /* The workflow validator reports the envelope error. */ }
60:       return { output, usage, execution: { runtime: 'pi-agent-context', sessionId: session.sessionId, contextHash: context.contentHash, cacheKey } };
61:     } finally {
62:       clearTimeout(timeout); input.signal.removeEventListener('abort', abort);
63:       unsubscribe(); session.dispose(); this.sessions.delete(session);
64:     }
65:   }
66: }

