187:   }
188:   relaunch(id: string, raw: unknown) {
189:     const input = relaunchExperimentSchema.parse(raw), hash = sha256(JSON.stringify(input));
190:     const work = async () => {
191:       await this.read(id);
192:       const experiment = (await this.store.read(id))!;
193:       let receipt = experiment.launches?.find(l => l.id === input.requestId);
194:       if (receipt && receipt.hash !== hash) throw new ApplicationError('conflict', 'Relaunch request ID already used for different edits.');
195:       if (receipt && experiment.samples.some(s => s.id === receipt!.sample.id)) return { experiment: this.public(experiment), runId: input.requestId };
196:       if (!receipt && input.expectedRevision !== experiment.revision) throw new ApplicationError('conflict', 'Experiment changed. Refresh before relaunching.');
197:       const sample = experiment.samples.find(s => s.id === input.sampleId), output = sample?.outputs.find(o => o.stageId === input.stageId);
198:       if (!sample || !output || !this.runs.launchEdited || !this.runs.editedPrompt) throw new ApplicationError('invalid-input', 'Choose an existing generation output to relaunch.');
199:       const source = await this.runs.read(output.runId);
200:       await this.runs.editedPrompt(source, output.cellKey, input.stages);
201:       if (!receipt) {
202:         const attempts = [...experiment.samples, ...(experiment.launches ?? []).map(l => l.sample)].filter(s => s.phaseId === sample.phaseId && s.caseId === sample.caseId && s.conditionId === sample.conditionId && s.number === sample.number);
203:         receipt = { id: input.requestId, hash, sample: { id: `attempt-${input.requestId}`, ...(sample.phaseId ? { phaseId: sample.phaseId } : {}), caseId: sample.caseId, conditionId: sample.conditionId, number: sample.number,
204:           attempt: Math.max(...attempts.map(s => s.attempt)) + 1, relaunchedFrom: { sampleId: sample.id, stageId: input.stageId }, outputs: [] } };
205:         experiment.launches = [...experiment.launches ?? [], receipt];
206:         await this.store.save(experiment);
207:       }
208:       const run = await this.runs.launchEdited(source.id, output.cellKey, input.stages, input.requestId);
209:       const selected = source.cells.find(c => c.key === output.cellKey)!;
210:       const outputs = sample.outputs.filter(o => o.runId === source.id).flatMap(o => {
211:         const before = source.cells.find(c => c.key === o.cellKey);
212:         if (!before || before.promptId !== selected.promptId || source.workflow !== 'few-shot-refinement' && before.pass !== selected.pass) return [];
213:         const cell = run.cells.find(c => c.stage === before.stage && c.pass === (source.workflow === 'few-shot-refinement' ? before.pass : 1));
214:         if (!cell) throw Error('Relaunched workflow did not produce the expected stage cell.');
215:         return [{ stageId: o.stageId, runId: run.id, cellKey: cell.key }];
216:       });
217:       experiment.samples.push({ ...receipt.sample, outputs }); experiment.revision++; experiment.updatedAt = new Date().toISOString();
218:       await this.store.save(experiment);
219:       return { experiment: this.public(experiment), runId: run.id };
220:     };
221:     const pending = this.writes.then(work); this.writes = pending.catch(() => {}); return pending;
222:   }
223: }

