13: /** Imports existing comparisons and materializes new evaluator results as independently typed records. */
14: export class JudgementService {
15:   private queue = Promise.resolve();
16:   constructor(private store: JudgementStore, private sessions: CompareSessionService, private comparisonStore: ComparisonRunStore,
17:     private comparisons: ComparisonGenerationService, private runs: EvalRunStore) {
18:     this.queue = store.list().then(async records => {
19:       for (const item of records) if (item.source.kind === 'eval-run' && !item.deletedAt && ['queued', 'generating'].includes(item.status))
20:         await store.save({ ...item, status: 'failed', error: 'Server restarted during evaluation. Completed rounds are retained.', updatedAt: new Date().toISOString() });
21:     });
22:   }
23:   private serialize<T>(task: () => Promise<T>): Promise<T> {
24:     const pending = this.queue.then(task); this.queue = pending.then(() => {}, () => {}); return pending;
25:   }
26:   private async reconcile() {
27:     const [sessions, jobs, existing, runs] = await Promise.all([this.sessions.list(), this.comparisonStore.list(), this.store.list(), this.runs.list()]);
28:     const records = new Map(existing.map(item => [item.id, item]));
29:     const jobsById = new Map(jobs.map(job => [job.sessionId ?? job.id, job]));
30:     const sources = new Set([...sessions.map(item => item.id), ...jobs.map(item => item.id)]);
31:     const subjects = (canvases: CompareCanvasCopy[]): JudgementSubject[] => canvases.map(copy => {
32:       const owner = runs.find(run => run.id === copy.generated?.runId) ?? runs.find(run => run.cells.some(cell => cell.canvasId === copy.source.documentId));
33:       const runId = owner?.id ?? copy.generated?.runId;
34:       const outputKey = owner?.cells.find(cell => cell.canvasId === copy.source.documentId)?.key;
35:       return { source: copy.source, ...(runId ? { runId } : {}), ...(outputKey ? { outputKey } : {}) };
36:     });
37:     const fingerprint = (job?: ComparisonRun) => JSON.stringify(job ? [job.status, job.completedAt, job.error, job.sessionId] : ['manual']);
38:     const save = async (sourceId: string, session: ComparePageSession | undefined, job: ComparisonRun | undefined) => {
39:       const canvases = session?.canvases ?? job!.canvases, refs = subjects(canvases);
40:       const common = { schemaVersion: 1 as const, projectId: session?.projectId ?? job!.projectId,
41:         title: session?.title ?? job!.request.title, createdAt: job?.createdAt ?? session!.createdAt, updatedAt: job?.completedAt ?? session?.createdAt ?? job!.createdAt,
42:         subjects: refs, runIds: [...new Set(refs.flatMap(ref => ref.runId ? [ref.runId] : []))], canvases,
43:         evaluator: job ? { kind: 'model' as const, model: job.request.model, effort: job.request.effort,
44:           ...(job.evaluationPrompt ? { prompt: job.evaluationPrompt, promptVersion: job.evaluationPromptVersion ?? 1 } : {}) } : { kind: 'manual' as const },
45:         status: session ? 'finished' as const : job!.status === 'finished' ? 'failed' as const : job!.status,
46:         error: !session && job?.status === 'finished' ? 'The saved comparison result is unavailable.' : job?.error, usage: job?.usage,
47:         source: { kind: 'comparison' as const, id: sourceId, fingerprint: fingerprint(job) } };
48:       const diagrams = session?.compares.filter(pair => pair.A.kind === 'diagram' && pair.B.kind === 'diagram') ?? [];
49:       const canvasesCompared = session?.compares.filter(pair => pair.A.kind !== 'diagram' && pair.B.kind !== 'diagram') ?? [];
50:       const results: Judgement[] = [];
51:       if (job?.request.experiment) results.push({ ...common, id: `${sourceId}-report`, kind: 'comparison-report', status: job.status, error: job.error, ...(job.report ? { data: job.report } : {}) });
52:       if (diagrams.length || !session && job && !job.request.experiment) results.push({ ...common, id: `${sourceId}-diagram`, kind: 'diagram-comparison',
53:         ...(diagrams.length ? { data: diagramJudgementSchema.parse({ comparisons: diagrams }) } : {}) });
54:       if (canvasesCompared.length) results.push({ ...common, id: `${sourceId}-canvas`, kind: 'canvas-comparison', data: canvasJudgementSchema.parse({
55:         comparisons: canvasesCompared.map(pair => ({ ...pair, A: { ...pair.A, kind: 'canvas' }, B: { ...pair.B, kind: 'canvas' } }))
56:       }) });
57:       for (const result of results) {
58:         if (result.data && result.kind !== 'few-shot-progress' && result.kind !== 'comparison-report' && result.kind !== 'diagram-change-tree') {
59:           const used = new Set(result.data.comparisons.flatMap(pair => [pair.A.canvasCopyId, pair.B.canvasCopyId]));
60:           result.canvases = canvases.filter(copy => used.has(copy.id));
61:           result.subjects = subjects(result.canvases);
62:           result.runIds = [...new Set(result.subjects.flatMap(ref => ref.runId ? [ref.runId] : []))];
63:         }
64:         const previous = records.get(result.id);
65:         if (previous?.deletedAt) continue;
66:         if (!previous || previous.status !== result.status || previous.source.fingerprint !== result.source.fingerprint || JSON.stringify(previous.subjects) !== JSON.stringify(result.subjects)) await this.store.save(result);
67:       }
68:     };
69:     for (const summary of sessions) {
70:       const job = jobsById.get(summary.id);
71:       // Completed session snapshots never change; avoid loading them again during polling.
72:       const previous = existing.filter(item => item.source.id === summary.id);
73:       if (previous.length && previous.every(item => item.deletedAt || item.status === 'finished' && item.source.fingerprint === fingerprint(job) && item.subjects.every(ref => ref.runId))) continue;
74:       await save(summary.id, await this.sessions.read(summary.id), job);
75:     }
76:     for (const job of jobs) if (!sessions.some(session => session.id === (job.sessionId ?? job.id))) await save(job.id, undefined, job);
77:     // Deletion through legacy comparison APIs also removes its imported judgements.
78:     for (const item of existing) if (item.source.kind === 'comparison' && !item.deletedAt && !sources.has(item.source.id)) await this.store.save({ ...item, deletedAt: new Date().toISOString() });
79:   }
80:   /** Native workflow results share the same durable store, without legacy import ownership. */
81:   saveDeterministic(item: Extract<Judgement, { kind: 'diagram-change-tree' }>) {
82:     return this.serialize(async () => {
83:       const previous = await this.store.read(item.id);
84:       if (previous) {
85:         if (previous.deletedAt || previous.source.fingerprint !== item.source.fingerprint) throw new ApplicationError('conflict', 'Judgement request ID already used.');
86:         return previous;
87:       }
88:       diagramChangeTreeResultSchema.parse(item.data);
89:       await this.store.save(structuredClone(item));
90:       return item;
91:     });
92:   }
93:   saveProgress(item: Extract<Judgement, { kind: 'few-shot-progress' }>) {
94:     return this.serialize(async () => {
95:       const previous = await this.store.read(item.id);
96:       if (previous?.deletedAt) return;
97:       if (item.data) fewShotProgressSchema.parse(item.data);
98:       await this.store.save(structuredClone(item));
99:     });
100:   }
101:   async list(runId?: string) {
102:     return this.serialize(async () => {
103:       await this.reconcile();
104:       return (await this.store.list()).filter(item => !item.deletedAt && (!runId || item.runIds.includes(runId)))
105:         .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id)).map(summarizeJudgement);
106:     });
107:   }
108:   async read(id: string) {
109:     return this.serialize(async () => {
110:       await this.reconcile();
111:       const item = await this.store.read(id);
112:       if (!item || item.deletedAt) throw new ApplicationError('invalid-input', 'Judgement not found.');
113:       return item;
114:     });
115:   }
116:   async delete(id: string) {
117:     return this.serialize(async () => {
118:       await this.reconcile();
119:       const item = await this.store.read(id);
120:       if (!item || item.deletedAt) return;
121:       await this.store.save({ ...item, deletedAt: new Date().toISOString() });
122:       if (item.source.kind === 'comparison' && (item.status === 'queued' || item.status === 'generating')) await this.comparisons.delete(item.source.id);
123:     });
124:   }
125: }
