33: export function copyCompareHistory(history: CanvasHistoryRecord, checkpointId: string): CanvasHistoryRecord {
34:   const checkpoint = history.snapshots[checkpointId];
35:   if (!checkpoint) throw new ApplicationError('conflict', 'The selected checkpoint is no longer available. Refresh the views.');
36:   const { parentId: _parent, transactionId: _transaction, ...head } = checkpoint;
37:   const revisions = Object.fromEntries(checkpointRevisionIds(checkpoint).map(id => [id, history.diagramRevisions[id]]));
38:   const copy: CanvasHistoryRecord = structuredClone({ schemaVersion: 1, contextId: randomUUID(),
39:     baselineId: checkpointId, headId: checkpointId, past: [], future: [], snapshots: { [checkpointId]: head }, diagramRevisions: revisions,
40:     revisionBoundary: Object.fromEntries(Object.values(revisions).flatMap(revision => revision?.parentId && !revisions[revision.parentId] ? [[revision.parentId, revision.diagramId]] : [])) });
41:   validateCanvasHistory(copy);
42:   return copy;
