103:     const capture = ({ documentId, viewId, checkpointId }: CompareSource) => {
104:       const source = { documentId, ...(viewId ? { viewId } : {}), checkpointId };
105:       const key = JSON.stringify(source);
106:       const previous = copies.get(key); if (previous) return previous;
107:       const generated = catalog.get(key);
108:       if (generated && !source.viewId && generated.history.snapshots[source.checkpointId]) {
109:         const history = copyCompareHistory(generated.history, source.checkpointId);
110:         history.snapshots[source.checkpointId].view ??= initialCanvasState();
111:         const copy: CompareCanvasCopy = { id: randomUUID(), source, canvasName: generated.generated.contextName, history, generated: structuredClone(generated.generated),
112:           view: { id: randomUUID(), name: generated.name, createdAt, savedAt: createdAt,
113:             startCheckpointId: source.checkpointId, finalCheckpointId: source.checkpointId, checkpointIds: [source.checkpointId] } };
