144:     return { projectId: index.projectId, canvases: [...copies.values()] };
145:   }
146:   async createPinned(input: unknown, captured: { projectId: string; canvases: CompareCanvasCopy[] }): Promise<ComparePageSession> {
147:     const request = createCompareSessionSchema.parse(input), requestHash = sha256(JSON.stringify(request));
