150:       const copy = copies.get(JSON.stringify({ documentId, ...(viewId ? { viewId } : {}), checkpointId }));
151:       if (!copy) throw new ApplicationError('invalid-input', 'Comparison source was not captured.');
152:       return copy;
153:     };
154:     const createdAt = new Date().toISOString();
155:     const pane = (copy: CompareCanvasCopy) => {
156:       const canvas = copy.history.snapshots[copy.history.headId].view as MappingCanvasState;
157:       // Same default as Mapping's native camera (360, 100, 1), in persisted coordinates.
158:       return { canvasCopyId: copy.id, camera: { transform: structuredClone(canvas?.viewport ?? { offset: { x: 170, y: 36 }, scale: 1 }) } };
159:     };
160:     const compares = request.pairs.map(pair => {
