165:           if (!pinned) throw new ApplicationError('invalid-input', `Unknown diagram: ${target.diagramId}`);
166:           if (pinned.revisionId !== target.revisionId) throw new ApplicationError('conflict', 'The selected diagram revision does not match this snapshot. Refresh the views.');
167:           if (target.ranges?.some(range => range.endLine > copy.history.diagramRevisions[target.revisionId].diagram.content.ascii.split('\n').length))
